import {travelCyclePose} from './travel-cycle.js';
import {prepareTrailMarkers,drawTrailMarkers,drawTravelEnd} from './trail-markers.js';
import {buildPreloadMaterial,clipPreloadFill,preloadGradient,tracePreloadHolder} from './preload-material.js';
const sources={},clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));let latest=null,flatBuffer=null,materialCache=null;
export async function preparePreloadSnapshots(){await prepareTrailMarkers();await Promise.all([['cube','./assets/selected-round-fill-states.png'],['star','./cube-editor/assets/puffy-star-original.png']].map(async([key,path])=>{const image=new Image();image.src=new URL(path,import.meta.url);await image.decode();const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d');if(key==='cube')ctx.drawImage(image,0,0,128,128,0,0,128,128);else ctx.drawImage(image,0,0,128,128);sources[key]=ctx.getImageData(0,0,128,128).data;}));}
export function preloadSnapshot(design,{width,side,tileHeight=side,count,pitch,fill,curveAt,key,time=0,tiltOffset=0,live=false,hops=[],travelCycle=null,barWindow=null}){
 if(latest?.key===key)return latest;
 const samples=Array.from({length:65},(_,i)=>curveAt(width*i/64).drop),min=Math.min(...samples),max=Math.max(...samples),pad=5,motionExtra=design.mode==='tiles'?Math.max(side,tileHeight)*2:0,markerExtra=motionExtra+(design.barStyle==='trail'&&design.trailMarkers?tileHeight*.85:0),base=tileHeight-min+pad+markerExtra,height=tileHeight+max-min+pad*2+markerExtra;
 const canvas=latest?.canvas??document.createElement('canvas'),density=live?2:3;canvas.width=Math.ceil((width+pad*2)*density);canvas.height=Math.ceil(height*density);const ctx=canvas.getContext('2d');ctx.scale(density,density);
 if(design.mode==='bar'){
  const flat=flatBuffer??=document.createElement('canvas');flat.width=Math.ceil(width*density);flat.height=Math.ceil(tileHeight*density);const c=flat.getContext('2d');c.scale(density,density);c.translate(width/2,tileHeight/2);tracePreloadHolder(c,width,tileHeight,design);c.fillStyle=design.holder;c.fill();c.clip();c.save();clipPreloadFill(c,width,tileHeight,barWindow?barWindow.right:fill,design,time,tiltOffset);if(barWindow){c.beginPath();c.rect(-width/2+width*barWindow.left,-tileHeight/2,width*(barWindow.right-barWindow.left),tileHeight);c.clip();}c.globalAlpha=design.fillStyle==='gas'?.72:1;c.fillStyle=preloadGradient(c,width,tileHeight,design);c.fillRect(-width/2,-tileHeight/2,width,tileHeight);
  const gloss=c.createLinearGradient(0,-tileHeight/2,0,tileHeight/2);gloss.addColorStop(0,`rgba(255,255,255,${design.highlight/150*.5})`);gloss.addColorStop(.4,'rgba(255,255,255,0)');gloss.addColorStop(1,`rgba(98,49,29,${design.volume/100*.2})`);c.fillStyle=gloss;c.fillRect(-width/2,-tileHeight/2,width,tileHeight);
  if(design.fillStyle!=='classic')for(let i=0;i<Math.round(design.bubbles/100*22);i++){const phase=time*design.flowSpeed/100,u=((i*.61803398875)+phase*(design.fillStyle==='sludge'?.018:.06))%1,v=(Math.sin(i*3.7+phase*(design.fillStyle==='gas'?.8:.3))+1)/2,r=tileHeight*(design.fillStyle==='gas'?.25:.08)*(1+i%3*.25);c.globalAlpha=design.fillStyle==='gas'?.2:.22;c.fillStyle=i%2?'#fff9eb':design.end;c.beginPath();c.ellipse(-width/2+u*width,-tileHeight*.35+v*tileHeight*.7,r*(design.fillStyle==='gas'?2:1),r,0,0,Math.PI*2);c.fill();}c.restore();
  for(let i=0;i<64;i++){const x0=width*i/64,x1=width*(i+1)/64,a=curveAt(x0).drop,b=curveAt(x1).drop,slope=(b-a)/(x1-x0);ctx.save();ctx.beginPath();ctx.rect(pad+x0,0,x1-x0+.1,height);ctx.clip();ctx.transform(1,slope,0,1,pad,base+a-tileHeight-slope*x0);ctx.drawImage(flat,0,0,width,tileHeight);ctx.restore();}
  ctx.save();ctx.translate(pad+width/2,base-tileHeight/2);drawTrailMarkers(ctx,width,tileHeight,design,curveAt);ctx.restore();
 }else{
  const materialKey=JSON.stringify(design),art=sources[design.shape==='cube'?'cube':'star'];if(materialCache?.key!==materialKey)materialCache={key:materialKey,empty:buildPreloadMaterial(false,design,art),full:buildPreloadMaterial(true,design,art)};const {empty,full}=materialCache;
  for(let i=0;i<count;i++){const x=design.shape==='travel'?side/2+i*Math.max(0,width-side*2-width*.02)/Math.max(1,count-1):side/2+i*pitch,curve=curveAt(x),raw=design.distribution==='together'?fill:clamp(fill*(count+(design.shape==='travel'?1:0))-i),amount=(design.shape==='travel'||design.shape==='cube')?(raw>=.999?1:0):raw;
   const plan=hops[i],age=plan?time-plan.at:10,u=clamp((age-.06)/.4),active=!!plan&&age>=0&&age<.7,b=design.bounce/100,squash=active?(age<.06?Math.sin(age/.06*Math.PI):age>.46&&age<.56?Math.sin((age-.46)/.1*Math.PI):0):0,stretch=active&&age>=.06&&age<.16?Math.sin((age-.06)/.1*Math.PI):0,sx=1+b*(.28*squash-.15*stretch),sy=1+b*(-.28*squash+.22*stretch),angle=active?plan.spin*Math.PI*2*u*u*(3-2*u):0,lift=active?4*u*(1-u)*tileHeight*design.lift/100*plan.lift:0;ctx.save();ctx.translate(pad+x,base+curve.drop);ctx.rotate(Math.atan(curve.slope));ctx.translate(0,-tileHeight/2-lift);ctx.rotate(angle);ctx.scale(sx,sy);if(travelCycle&&design.shape==='travel'){const p=travelCyclePose(travelCycle,i,time,tileHeight);ctx.translate(0,p.y);ctx.rotate(p.angle);ctx.scale(p.sx,p.sy);}ctx.shadowColor=`rgba(106,77,56,${design.shadow/100*.35})`;ctx.shadowBlur=tileHeight*.2;ctx.shadowOffsetY=tileHeight*.08;ctx.drawImage(empty,-side/2,-tileHeight/2,side,tileHeight);ctx.shadowColor='transparent';ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.save();clipPreloadFill(ctx,side,tileHeight,amount,design,time,tiltOffset);ctx.drawImage(full,-side/2,-tileHeight/2,side,tileHeight);ctx.restore();ctx.restore();}
  if(design.shape==='travel'){const x=width-side/2,c=curveAt(x);ctx.save();ctx.translate(pad+x,base+c.drop-tileHeight/2);ctx.rotate(Math.atan(c.slope));if(travelCycle){const p=travelCyclePose(travelCycle,count,time,side);ctx.translate(0,p.y);ctx.rotate(p.angle);ctx.scale(p.sx,p.sy);}drawTravelEnd(ctx,0,0,side*.95,0,design.empty,clamp(fill*(count+1)-count),design.end);ctx.restore();}
 }
 latest={key,canvas,url:live?null:canvas.toDataURL(),pad,base,height,width:width+pad*2};return latest;
}
